CustomField.formula:
IF(
  OR(
    ISPICKVAL(Program_Stage__c, "Referred"),
    ISPICKVAL(Program_Stage__c, "Applicant"),
    ISPICKVAL(Program_Stage__c, "Resource Only"),
    ISBLANK(Program_Start_Date__c),
    Program_Start_Date__c > TODAY(),
    Inactive_Date__c < Program_Start_Date__c
  ),
0,
  IF( NOT( ISBLANK(Inactive_Date__c)),
  Inactive_Date__c - Program_Start_Date__c + 1,
  TODAY() - Program_Start_Date__c + 1
  )
)

